It is proved (Dzhafarov, Kujala, \& Larsson, 2015; Kujala \& Dzhafarov,
2016) that the EPR/BB system is noncontextual if and only if

\begin{equation}
\begin{array}{r}
\max_{k,l\in\left\{ 1,2\right\} }\left|\sum_{i,j\in\left\{ 1,2\right\} }\mathsf{E}\left[A_{i}^{j}B_{j}^{i}\right]-2\mathsf{E}\left[A_{k}^{l}B_{l}^{k}\right]\right|\\
\\
-\sum_{i\in\left\{ 1,2\right\} }\left|\mathsf{E}\left[A_{i}^{1}\right]-\mathsf{E}\left[A_{i}^{2}\right]\right|\\
\\
-\sum_{j\in\left\{ 1,2\right\} }\left|\mathsf{E}\left[B_{j}^{1}\right]-\mathsf{E}\left[B_{j}^{2}\right]\right|-2\leq0.
\end{array}\label{eq:modCHSH}
\end{equation}

\begin{equation}
\begin{array}{r}
\max_{k,l\in\left\{ 1,2\right\} }\left|\sum_{i,j\in\left\{ 1,2\right\} }\mathsf{E}\left[A_{i}^{j}B_{j}^{i}\right]-2\mathsf{E}\left[A_{k}^{l}B_{l}^{k}\right]\right|\\
\\
-\sum_{i\in\left\{ 1,2\right\} }\left|\mathsf{E}\left[A_{i}^{1}\right]-\mathsf{E}\left[A_{i}^{2}\right]\right|\\
\\
-\sum_{j\in\left\{ 1,2\right\} }\left|\mathsf{E}\left[B_{j}^{1}\right]-\mathsf{E}\left[B_{j}^{2}\right]\right|-2\leq0.
\end{array}\label{eq:modCHSH}
\end{equation}

